import React, { useState } from "react";
import {
    Container, Paper, Typography, TextField, Button, Grid, Snackbar, Alert,
    CircularProgress, IconButton, Stack
} from "@mui/material";
import { ArrowBack } from "@mui/icons-material";
import axios from "axios";

function CandidateRegistration() {
    const [step, setStep] = useState(1);
    const [loading, setLoading] = useState(false);
    const [numCarteElecteur, setNumCarteElecteur] = useState("");
    const [baseInfo, setBaseInfo] = useState(null);
    const [error, setError] = useState("");
    const [success, setSuccess] = useState(false);
    const [openSnackbar, setOpenSnackbar] = useState(false);

    const [complementData, setComplementData] = useState({
        email: "",
        telephone: "",
        parti: "",
        slogan: "",
        couleur1: "#000000",
        couleur2: "#000000",
        couleur3: "#000000",
        urlInfo: "",
    });

    const handleVerify = async () => {
        if (!numCarteElecteur.trim()) {
            setError("Veuillez entrer un numéro de carte.");
            setOpenSnackbar(true);
            return;
        }

        setError("");
        setLoading(true);
        try {
            const response = await axios.get(
                `http://localhost:5000/api/electeurs/check?num=${numero_carte_electeur}`
            );
            const data = response.data;

            if (!data.exists) {
                setError("Le candidat n’est pas présent dans le fichier électoral.");
            } else if (data.registered) {
                setError("Ce candidat est déjà enregistré.");
            } else {
                setBaseInfo({
                    nom: data.nom,
                    prenom: data.prenom,
                    date_naissance: data.date_naissance,
                });
                setStep(2);
            }
        } catch (err) {
            setError("Erreur lors de la vérification. Veuillez réessayer.");
        }
        setLoading(false);
        setOpenSnackbar(true);
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setError("");
        setLoading(true);

        if (!complementData.email.trim() || !complementData.telephone.trim()) {
            setError("Email et téléphone sont obligatoires.");
            setOpenSnackbar(true);
            setLoading(false);
            return;
        }

        try {
            const fullData = { numCarteElecteur, ...baseInfo, ...complementData };
            await axios.post("http://localhost:5000/api/candidat", fullData);
            setSuccess(true);
            setStep(1);
            setNumCarteElecteur("");
            setBaseInfo(null);
            setComplementData({
                email: "",
                telephone: "",
                parti: "",
                slogan: "",
                couleur1: "#000000",
                couleur2: "#000000",
                couleur3: "#000000",
                urlInfo: "",
            });
        } catch (err) {
            setError("Erreur lors de l'enregistrement du candidat.");
        }
        setLoading(false);
        setOpenSnackbar(true);
    };

    return (
        <Container maxWidth="sm">
            <Paper elevation={4} sx={{ p: 4, mt: 4, borderRadius: 3 }}>
                {step === 1 && (
                    <>
                        <Typography variant="h5" textAlign="center" gutterBottom>
                            Vérification de l'Électeur
                        </Typography>
                        <TextField
                            fullWidth
                            label="Numéro de carte d’électeur"
                            value={numCarteElecteur}
                            onChange={(e) => setNumCarteElecteur(e.target.value)}
                            sx={{ mb: 2 }}
                        />
                        <Button
                            variant="contained"
                            color="primary"
                            fullWidth
                            onClick={handleVerify}
                            disabled={loading || !numCarteElecteur.trim()}
                            startIcon={loading && <CircularProgress size={20} color="inherit" />}
                        >
                            {loading ? "Vérification..." : "Vérifier"}
                        </Button>
                    </>
                )}

                {step === 2 && baseInfo && (
                    <>
                        <IconButton onClick={() => setStep(1)}>
                            <ArrowBack />
                        </IconButton>
                        <Typography variant="h6" gutterBottom>
                            Informations de l'Électeur
                        </Typography>
                        <Typography>
                            <strong>Nom :</strong> {baseInfo.nom}
                        </Typography>
                        <Typography>
                            <strong>Prénom :</strong> {baseInfo.prenom}
                        </Typography>
                        <Typography>
                            <strong>Date de naissance :</strong> {baseInfo.date_naissance}
                        </Typography>

                        <Typography variant="h6" gutterBottom sx={{ mt: 3 }}>
                            Informations Complémentaires
                        </Typography>
                        <form onSubmit={handleSubmit}>
                            <Grid container spacing={2}>
                                <Grid item xs={12}>
                                    <TextField
                                        fullWidth
                                        label="Email"
                                        name="email"
                                        required
                                        value={complementData.email}
                                        onChange={(e) =>
                                            setComplementData({ ...complementData, email: e.target.value })
                                        }
                                    />
                                </Grid>
                                <Grid item xs={12}>
                                    <TextField
                                        fullWidth
                                        label="Téléphone"
                                        name="telephone"
                                        required
                                        value={complementData.telephone}
                                        onChange={(e) =>
                                            setComplementData({ ...complementData, telephone: e.target.value })
                                        }
                                    />
                                </Grid>
                                <Grid item xs={12}>
                                    <TextField
                                        fullWidth
                                        label="Parti Politique (facultatif)"
                                        name="parti"
                                        value={complementData.parti}
                                        onChange={(e) =>
                                            setComplementData({ ...complementData, parti: e.target.value })
                                        }
                                    />
                                </Grid>
                                <Grid item xs={12}>
                                    <TextField
                                        fullWidth
                                        label="Slogan (facultatif)"
                                        name="slogan"
                                        value={complementData.slogan}
                                        onChange={(e) =>
                                            setComplementData({ ...complementData, slogan: e.target.value })
                                        }
                                    />
                                </Grid>
                                <Grid item xs={12}>
                                    <Stack direction="row" spacing={2}>
                                        <TextField
                                            fullWidth
                                            label="Couleur 1"
                                            type="color"
                                            value={complementData.couleur1}
                                            onChange={(e) =>
                                                setComplementData({ ...complementData, couleur1: e.target.value })
                                            }
                                        />
                                        <TextField
                                            fullWidth
                                            label="Couleur 2"
                                            type="color"
                                            value={complementData.couleur2}
                                            onChange={(e) =>
                                                setComplementData({ ...complementData, couleur2: e.target.value })
                                            }
                                        />
                                        <TextField
                                            fullWidth
                                            label="Couleur 3"
                                            type="color"
                                            value={complementData.couleur3}
                                            onChange={(e) =>
                                                setComplementData({ ...complementData, couleur3: e.target.value })
                                            }
                                        />
                                    </Stack>
                                </Grid>
                                <Grid item xs={12}>
                                    <Button type="submit" variant="contained" color="primary" fullWidth disabled={loading}>
                                        {loading ? "Enregistrement..." : "Enregistrer le Candidat"}
                                    </Button>
                                </Grid>
                            </Grid>
                        </form>
                    </>
                )}
            </Paper>

            <Snackbar open={openSnackbar} autoHideDuration={4000} onClose={() => setOpenSnackbar(false)}>
                <Alert severity={error ? "error" : "success"}>{error || "Candidat ajouté avec succès !"}</Alert>
            </Snackbar>
        </Container>
    );
}

export default CandidateRegistration;
